package com.stocksmart.rfid;

import java.time.Instant;

/**
 * One tag read as surfaced by an {@link RfidReader}, before any business
 * validation or product mapping is applied.
 *
 * @param epcCode   raw tag identifier as reported by the reader
 * @param eventAt   reader/event timestamp
 * @param simulated true when generated by the simulator (never hardware)
 * @param readerName source reader name
 */
public record RfidRead(String epcCode, Instant eventAt, boolean simulated, String readerName) {
}
